func TestMatchTiers(t *testing.T) {
	// s1 composes "Aria" (prefix), s2 carries it mid-name (substring),
	// s3 only as an unpicked alternate (lowest tier) — one query, three
	// tiers, served strictly best-first.
	ix := NewSearchIndex([]Entry{
		{ID: "s1", LibraryID: "lib1", Kind: KindSeries, DisplayName: "Aria"},
		{ID: "s2", LibraryID: "lib1", Kind: KindSeries, DisplayName: "The Aria Story"},
		{ID: "s3", LibraryID: "lib1", Kind: KindSeries, DisplayName: "Собрание сочинений",
			Alternates: []string{"Aria anthology"}},
		{ID: "s4", LibraryID: "lib1", Kind: KindSeries, DisplayName: "Unrelated"},
	})

	tests := []struct {
		name  string
		query string
		want  []string
	}{
		{"tiers rank prefix > substring > alternate", "aria", []string{"s1", "s2", "s3"}},
		{"prefix tier", "the aria", []string{"s2"}},
		{"substring tier", "story", []string{"s2"}},
		{"alternate tier", "anthology", []string{"s3"}},
		{"no match is empty, not error", "zzz", []string{}},
		{"empty query matches nothing", "", []string{}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := ix.Search(tt.query).Series
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf("Search(%q) series = %v, want %v", tt.query, got, tt.want)
			}
		})
	}
}

func TestYoFoldBidirectional(t *testing.T) {
	// Bidirectional ё→е: each entry spelling is hit by the query's other
	// spelling, in both directions, across both cases — the one shared
	// fold applied at write and query time. One entry per case, so a hit
	// is unambiguous.
	tests := []struct {
		name      string
		entryName string
		query     string
	}{
		{"entry ё hit by query е", "Ёлка", "елка"},
		{"entry е hit by query ё", "Елка", "ёлка"},
		{"entry Ё (upper, write-time fold) hit by query е", "ЁЛКА", "елка"},
		{"entry е hit by query Ё (upper)", "Елка", "ЁЛКА"},
		{"ё inside a longer name hit by е query", "Пётр и Волк", "петр"},
		{"е inside a longer name hit by ё query", "Ежик в тумане", "ёжик"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			ix := NewSearchIndex([]Entry{
				{ID: "e1", LibraryID: "lib1", Kind: KindSeries, DisplayName: tt.entryName},
			})
			got := ix.Search(tt.query).Series
			if len(got) != 1 || got[0] != "e1" {
				t.Errorf("Search(%q) over %q = %v, want [e1]", tt.query, tt.entryName, got)
			}
		})
	}
}

func TestBoundedGroups(t *testing.T) {
	entries := make([]Entry, 0, 22)
	for i := 1; i <= 12; i++ {
		entries = append(entries, Entry{
			ID: fmt.Sprintf("s%02d", i), LibraryID: "lib1", Kind: KindSeries,
			DisplayName: fmt.Sprintf("serial %02d", i),
		})
	}
	for i := 1; i <= 10; i++ {
		entries = append(entries, Entry{
			ID: fmt.Sprintf("i%02d", i), LibraryID: "lib1", Kind: KindItem,
			DisplayName: fmt.Sprintf("item %02d", i),
		})
	}
	h := NewSearchIndex(entries).Search("0")

	tests := []struct {
		name string
		got  []string
		want []string
	}{
		{"series bound at 8, best-ranked kept", h.Series,
			[]string{"s01", "s02", "s03", "s04", "s05", "s06", "s07", "s08"}},
		{"items bound at 8, best-ranked kept", h.Items,
			[]string{"i01", "i02", "i03", "i04", "i05", "i06", "i07", "i08"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if !reflect.DeepEqual(tt.got, tt.want) {
				t.Errorf("group = %v, want %v", tt.got, tt.want)
			}
		})
	}

	// The bound is per group: a group under the cap is served whole.
	small := NewSearchIndex(entries[:3]).Search("0")
	if got := small.Series; len(got) != 3 {
		t.Errorf("under-cap group length = %d, want 3", len(got))
	}
	if got := small.Items; len(got) != 0 {
		t.Errorf("item group with no item entries = %v, want empty", got)
	}
}

func TestAlphabeticalTiebreak(t *testing.T) {
	// Same tier (all prefix hits), insertion order scrambled: served
	// display-name asc, then id asc for equal names.
	ix := NewSearchIndex([]Entry{
		{ID: "zz", LibraryID: "lib1", Kind: KindSeries, DisplayName: "Titanic"},
		{ID: "aa", LibraryID: "lib1", Kind: KindSeries, DisplayName: "Tilt"},
		{ID: "b2", LibraryID: "lib1", Kind: KindSeries, DisplayName: "Tin"},
		{ID: "b1", LibraryID: "lib1", Kind: KindSeries, DisplayName: "Tin"},
		{ID: "mm", LibraryID: "lib1", Kind: KindSeries, DisplayName: "Time"},
	})
	got := ix.Search("ti").Series
	want := []string{"aa", "mm", "b1", "b2", "zz"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Search(%q) series = %v, want %v", "ti", got, want)
	}
}
